/* ── ПОМЕЩЕНИЯ ── */
D({ rooms: {
  /* Приёмный покой */
  v11_admission: { n: "Приёмный зал", desc: "Огромный зал с рядами деревянных скамей, где веками ждали вызова. Табло над окошками щёлкает номерами, динамик ласково зовёт следующего, и голос долго гуляет под сводом. У стены — автомат с бахилами и автомат с горячим чаем для тех, кто ждёт; каменная плитка стёрта колёсами каталок до желобов.",
    obj: { terminal: .5, desk: .4, pc: .4, vending: .3, drinks: .3 }, loot: "paper", sign: ["Ожидайте вызова", "Жалобы — в порядке очереди"], amb: "room_hum", fl: "stone" },
  v11_triage: { n: "Сортировочная", desc: "Сюда из приёмного покоя свозили всех поступивших и делили на три очереди: «ждать», «срочно» и «поздно». На крюках висят бирки с насечками — их читают пальцами, и очереди здесь различают на ощупь. Каталки стоят вдоль стен, и колесо у одной тихо поскрипывает само по себе.",
    obj: { medst: .6, crate: .4, terminal: .3, locker: .3 }, loot: "med", sign: ["Сортировка", "Бирку не снимать"], amb: "room_medical", fl: "tile" },
  v11_registry: { n: "Регистратура", desc: "Деревянные стеллажи до потолка, в ячейках — карточки: на каждого, кто хоть раз болел, и на каждую руку, выданную в прокат. Картотека шелестит от сквозняка, ящики выдвигаются с сухим стуком, а машинка у окошка сама отстукивает карточки за тех, кто уже не придёт. Самые старые заперты в несгораемом шкафу.",
    obj: { pc: .6, desk: .5, locker: .4, safe: .2 }, loot: "paper", sign: ["Карточки на руки не выдаются", "Регистратура"], amb: "room_hum", fl: "wood" },
  /* Палатный корпус */
  v11_nursepost: { n: "Сестринский пост", desc: "Стойка поста в развилке коридоров: пульт вызовов с рядами лампочек, журнал назначений, шкаф с ампулами под стеклом. Пульт звенит, когда в палате нажимают кнопку, — и звенит до сих пор, хотя подходить некому. Кафель у стойки протёрт резиновыми подошвами тех, кто здесь дежурил.",
    obj: { pc: .6, desk: .5, medst: .5, safe: .3, terminal: .3 }, loot: "med", sign: ["Пост", "Без вызова не беспокоить"], amb: "room_hum", fl: "tile" },
  v11_ward: { n: "Общая палата", desc: "Длинная палата на двадцать коек: шторы на рельсах шуршат, кнопки вызова над изголовьями тихо пощёлкивают, в каждой тумбочке — кружка, ложка и бирка с номером. Ковролин глушит шаги, чтобы не будить больных. Спят здесь и теперь: за одной из штор кто-то дышит ровно и глубоко, а над соседней койкой бормочет радиоприёмник.",
    obj: { capsule: .5, medst: .5, locker: .5, radio: .2 }, loot: "med", sign: ["Тихий час", "Посещения — по списку"], safe: true, amb: "room_medical", fl: "carpet" },
  v11_longstay: { n: "Палата хроников", desc: "Самая старая палата корпуса, где живут хроники — те, кого прокатные протезы не отпускают из Лечебницы. Пульсомеры под потолком заклеены пластырем, шторы сшиты в стены, на тумбочках — вязанье, шашки и радиоприёмник с треснувшим корпусом, а у двери урчит кофейный автомат, который хроники починили сами. Здесь говорят вполголоса и замолкают, когда в коридоре скрипят колёса.",
    obj: { capsule: .4, locker: .5, radio: .4, coffee: .3, desk: .3 }, loot: "food", sign: ["Своих не сдаём", "Стучать трижды"], amb: "room_hum", fl: "carpet", dark: true },
  v11_academic: { n: "Палата ожидания", desc: "Одноместная палата, которую веками держат готовой для Академика: постель застелена, тапочки стоят носками к двери, в стакане свежая вода — её меняют каждое утро. На тумбочке лежит заведённая карта с пустыми графами, у изголовья еле слышно шуршит радиоприёмник. Здесь тихо, как в комнате, где кого-то очень ждут.",
    obj: { capsule: .6, desk: .4, radio: .3, locker: .3 }, loot: "paper", sign: ["Занято", "Для того, кто спустится следом"], safe: true, amb: "room_hum", fl: "carpet" },
  v11_linen: { n: "Бельевая", desc: "Тесная комната, до потолка забитая стопками простыней, халатов и наволочек. Бельё глотает звук, как вата: шаги пропадают, голоса гаснут, и пульсомерам тут нечего слушать — потому их здесь и не вешали. Пахнет крахмалом и немного табаком: санитары бегали сюда покурить.",
    obj: { locker: .6, crate: .5 }, loot: "armor", sign: ["Бельевая", "Чистое не трогать"], amb: "room_hum", fl: "wood", dark: true, util: true },
  /* Операционный блок */
  v11_theatre: { n: "Операционная", desc: "Стол посреди зала, над ним — кольцо ламп, гудящих в один тон, и манипуляторы, сложенные, как лапы спящего насекомого. Лотки с инструментом звякают от каждого шага, а в стоке под столом журчит вода: её не перекрыли с последней операции. Здесь же вживляли импланты — у стены ждёт своего часа имплантационная стойка.",
    obj: { implantlab: .5, medst: .6, terminal: .4, locker: .3 }, loot: "med", sign: ["Идёт операция", "Стерильно"], amb: "room_medical", fl: "tile" },
  v11_scrub: { n: "Предоперационная", desc: "Ряд раковин с локтевыми кранами, автоклавы и вешалки с накрахмаленными халатами. Вода из кранов течёт горячая, пар оседает на кафеле, и всё пахнет мылом и спиртом. Перед дверью в операционную лежит коврик, пропитанный раствором, — он хлюпает под ногой.",
    obj: { locker: .6, medst: .5, crate: .3 }, loot: "med", sign: ["Мыть руки — пять минут", "Дальше — стерильно"], amb: "room_drip", fl: "tile" },
  v11_examtheatre: { n: "Учебная операционная", desc: "Амфитеатр над операционным столом: деревянные скамьи поднимаются ярусами, и с любой из них слышно, как падает игла на кафель. Здесь сдавали экзамен на допуск к скальпелю — на слух и при всех. Стенд экзаменатора внизу, у стола, до сих пор ждёт следующего.",
    obj: { puzzle: .7, desk: .4, pc: .3, medst: .3 }, loot: "paper", sign: ["Экзамен", "Тишина в амфитеатре"], amb: "room_ring", fl: "wood", trial: true },
  /* Протезные мастерские */
  v11_limbshop: { n: "Протезная мастерская", desc: "Верстаки с тисками, а под потолком на крюках покачиваются руки и ноги — стальные, деревянные, на ремнях и шарнирах; от сквозняка они постукивают друг о друга, как ветряные колокольчики. Пахнет маслом и кожей ремней. Дощатый пол усыпан стружкой и мелкими винтами, у стены стоит станок для вживления протезов, у двери — зарядная стойка для протезных батарей.",
    obj: { workbench: .7, implantlab: .4, crate: .4, charger: .3 }, loot: "parts", sign: ["Подгонка — по записи", "Чужие руки не примерять"], amb: "room_factory", fl: "wood" },
  v11_rental: { n: "Пункт проката", desc: "Окошко выдачи, деревянный барьер и стеллажи за ним: на каждой полке — рука или нога с биркой «выдано» или «возврат». Здесь выдавали конечности, как инструмент со склада, и записывали в книгу проката срок, плату и фамилию. Счётная машинка у окошка щёлкает сама, досчитывая чьи-то долги, а книгу проката на ночь запирают в сейф.",
    obj: { terminal: .5, desk: .5, pc: .5, safe: .3, crate: .3 }, loot: "tech", sign: ["Прокат конечностей", "Просрочка — отзыв"], amb: "room_hum", fl: "carpet" },
  v11_fitting: { n: "Примерочная", desc: "Комната подгонки протезов: поручни вдоль стен и звонкий стальной настил, отзывающийся на каждый шаг, — по щелчкам мастер слышал, где жмёт. На стене таблица шагов, выбитая точками для пальцев. Станок подгонки гудит и ждёт ногу, а на зарядной стойке попискивают батареи прокатных суставов.",
    obj: { implantlab: .5, charger: .5, locker: .3 }, loot: "tech", sign: ["Подгонка", "Шаг — ровно"], amb: "room_electric", fl: "v11_fitdeck" },
  v11_fundvault: { n: "Хранилище фонда", desc: "Холодное хранилище за решёткой: здесь лежат лучшие протезы и импланты Лечебницы, которые выдают только по высокому допуску. Каждый — в своём ложементе, под стеклом и с номером, и в тишине слышно, как тикают их батареи. Решётка открывается не ключом, а статусом в списках.",
    obj: { safe: .6, locker: .6, crate: .5, implantlab: .3 }, loot: "tech", sign: ["Только с допуска", "Фонд Лечебницы"], amb: "room_fridge", fl: "stone", rank: 2 },
  /* Реанимация */
  v11_icu: { n: "Реанимационный зал", desc: "Ряды коек под прозрачными колпаками, у каждой — дыхательный аппарат, и все они вздыхают почти в лад, как один большой спящий. Мониторы пищат на разные голоса, складываясь в странный аккорд; если один сбивается с ритма, по залу проходит тревожная трель. Вдоль стены гудят зарядные стойки аппаратов, резиновый пол пружинит и гасит шаги.",
    obj: { capsule: .5, medst: .7, charger: .4, terminal: .3 }, loot: "med", sign: ["Реанимация", "Не входить без вызова"], amb: "room_medical", fl: "rubber" },
  v11_oxygen: { n: "Кислородная станция", desc: "Компрессоры, баллоны в стойках и трубы, по которым дыхание расходится по всем палатам. Вентили шипят, манометры дрожат, а воздух такой густой и свежий, что кружится голова. Табличка у двери напоминает: искрить нельзя, стрелять — тем более.",
    obj: { crate: .5, terminal: .4, locker: .3 }, loot: "parts", sign: ["Не курить. Не искрить", "Кислород"], amb: "room_compressor", fl: "concrete", util: true },
  v11_barochamber: { n: "Барокамера", desc: "Стальная бочка с иллюминатором и дверью толщиной в ладонь: внутри лечили давлением. Когда створки смыкаются, звук снаружи пропадает, уши закладывает, и слышно только своё сердце и шипение клапанов. На пульте — испытательный стенд: здесь проверяли, кто выдержит давление.",
    obj: { puzzle: .6, terminal: .5, medst: .3 }, loot: "med", sign: ["Давление!", "Испытание — по вызову"], amb: "room_pumps", fl: "v11_baro", trial: true },
  /* Аптечный двор */
  v11_pharmacy: { n: "Аптека", desc: "Окошко с латунной тарелкой для рецептов, за ним — шкафы до потолка, сотни ящичков с надписями, выдавленными для пальцев. Весы звякают гирьками, ступка стоит наготове, а трубы пневмопочты под потолком время от времени ухают, выплёвывая пустые капсулы рецептов. У входа — автомат с бинтами и пластырем, а сильнодействующее заперто в сейфе за окошком.",
    obj: { vending: .4, safe: .4, desk: .5, pc: .4, locker: .4 }, loot: "chem", sign: ["Без рецепта не отпускаем", "Аптека"], amb: "room_hum", fl: "wood" },
  v11_herbgarden: { n: "Аптекарский огород", desc: "Грядки под лампами, мягкая влажная земля и запах мяты, полыни и ромашки, такой густой, что его почти слышно. Капельные трубки тикают, как часы, между грядками жужжат опылители, а на садовом верстаке сушатся пучки трав. Отсюда шло всё, что Лечебница не могла выварить в колбах.",
    obj: { crate: .4, terminal: .3, workbench: .3 }, loot: "bio", sign: ["Траву не рвать", "Полив — по часам"], amb: "room_drip", fl: "grass" },
  v11_compound: { n: "Рецептурная", desc: "Комната провизоров: столы с ретортами и перегонными кубами, полки с банками, весы под стеклом. Здесь смешивали лекарства по рецептам, и каждый рецепт полагалось проверить на слух — по звону капли о дно мензурки. В кубах до сих пор что-то тихо булькает.",
    obj: { workbench: .6, puzzle: .3, locker: .4, crate: .3 }, loot: "chem", sign: ["Рецептурная", "Взвешивать дважды"], amb: "room_bubbles", fl: "tile" },
  /* Станция крови */
  v11_donorhall: { n: "Донорский зал", desc: "Ряд откидных кресел, у каждого — насос и пустая банка на штативе, у стены — лежаки, где донор отлёживался после сдачи. Табло над входом до сих пор показывает план смены, а насосы иногда вздрагивают, будто ищут вену. В углу — автомат со сладким донорским чаем: сестра выдавала стакан каждому, кто сдал норму.",
    obj: { medst: .5, capsule: .3, drinks: .4, crate: .3 }, loot: "food", sign: ["Норма донора — по списку", "Чай — после сдачи"], amb: "room_pumps", fl: "tile" },
  v11_centrifuge: { n: "Центрифужная", desc: "Центрифуги в ряд вдоль стены: тяжёлые барабаны раскручиваются с воем, поднимающимся до свиста, и разделяют кровь на слои. Пробирки в штативах звенят от дрожи пола, а на рабочем столе лежит набор для ремонта роторов. Сейчас крутится только одна — и никто не знает, кто её включил.",
    obj: { terminal: .5, workbench: .4, crate: .4, locker: .3 }, loot: "bio", sign: ["Крышку не открывать до остановки", "Центрифужная"], amb: "room_compressor", fl: "tile" },
  v11_bloodbank: { n: "Банк крови", desc: "Холодильные шкафы от пола до потолка, в них — пакеты крови с бирками: группа, дата, фамилия донора. Компрессоры гудят ровно, иней хрустит на петлях дверец. Кровь здесь считают, как деньги: в книге учёта у каждого пакета — приход и расход, а особые пакеты держат в отдельном сейфе.",
    obj: { safe: .5, locker: .5, crate: .4, terminal: .3 }, loot: "med", sign: ["Банк крови", "Дверцы закрывать плотно"], amb: "room_fridge", fl: "concrete" },
  /* Заразный корпус */
  v11_isolator: { n: "Изолятор", desc: "Стеклянные боксы вдоль прохода, у каждого — шлюз и решётка переговорного устройства. Из решёток иногда доносится дыхание или стук пальцами по стеклу — изнутри. Уплотнители дверей вздыхают, когда меняется давление, а хлоркой пахнет так, что щиплет в носу. В каждом боксе — койка и радиоприёмник: больного держали здесь, пока не выздоровеет, и старались, чтобы ему не было слишком тихо.",
    obj: { capsule: .4, medst: .6, radio: .3, locker: .3 }, loot: "med", sign: ["Заразно", "Не входить без костюма"], amb: "room_hum", fl: "tile" },
  v11_decon: { n: "Дезкамера", desc: "Камера санобработки между чистой и грязной зоной: из форсунок бьёт горячий раствор, по решёткам стоков бежит вода, вентиляция ревёт. Створки не откроются, пока не кончится цикл, — стоишь и слушаешь, как раствор барабанит по плечам. На крючках висят защитные костюмы со шлемами.",
    obj: { locker: .6, crate: .3, terminal: .3 }, loot: "armor", sign: ["Цикл — четыре минуты", "Грязная зона"], amb: "room_drip", fl: "v11_decon" },
  v11_post_cordon: { n: "Кордонный пост", desc: "Будка поста у границы заразной зоны: барьер, журнал проходов, переговорная решётка в стене и терминал, где отмечали каждого, кто входил и выходил. Отсюда решали, кого пропустить к палатам и кого — назад. Терминал тихо пищит, а за стеклом гудит поле кордона, ровное, как натянутая струна.",
    obj: { terminal: .7, desk: .4, pc: .4, locker: .4 }, loot: "arms", sign: ["Кордон", "Проход — по допуску"], amb: "room_electric", fl: "rubber" },
  /* Холодный корпус */
  v11_morgue: { n: "Морг", desc: "Холодная комната с выдвижными ящиками в стенах: каждый выкатывается с долгим грохотом роликов, и на каждом — бирка с именем, снятым со списков; вещи ушедших запирают в стенной сейф. Компрессоры гудят низко, капает конденсат, и шаги по мокрому бетону отдаются глухо. Здесь тихо, но не пусто.",
    obj: { corpse: .6, locker: .5, crate: .4, safe: .2 }, loot: "bio", sign: ["Морг", "Тишина"], amb: "room_cryo", fl: "concrete" },
  v11_returns: { n: "Склад возврата", desc: "Сюда свозили всё, что отозвали: руки, ноги и импланты тех, кто выбыл из списков или не заплатил за прокат. Ящики подписаны мелом, протезы свалены грудами и звякают, если задеть, а на верстаке отделяли годное от лома. Пульсомеров здесь не вешали: фонд не любит считать вслух, сколько он забрал.",
    obj: { crate: .7, locker: .5, workbench: .4 }, loot: "parts", sign: ["Возврат", "Принято без описи"], amb: "room_hum", fl: "concrete", dark: true, util: true },
  v11_farewell: { n: "Прощальная", desc: "Небольшой зал с деревянными скамьями и кафедрой: здесь в последний раз читали имя вслух, прежде чем вычеркнуть его из списков. Над кафедрой висит колокол, который звонит один раз, а в углу стоит радиоприёмник: по нему имя читали тем, кто не смог прийти. Акустика такая, что шёпот у кафедры слышен на последней скамье.",
    obj: { radio: .4, desk: .4 }, loot: "paper", sign: ["Прощальная", "Говорите тише"], safe: true, amb: "room_hum", fl: "wood" },
  /* Восстановительный корпус */
  v11_track: { n: "Терренкур", desc: "Песчаная дорожка петлёй вокруг зала, с поручнями и отметками через каждые десять шагов: здесь учили ходить на новых ногах. Песок хрустит и проседает, и протез на нём учится чувствовать опору. Посреди зала — испытательный стенд и табло, которое до сих пор щёлкает чьим-то лучшим кругом, у поручней — зарядные стойки для протезов.",
    obj: { puzzle: .4, charger: .4, medst: .3, locker: .3 }, loot: "armor", sign: ["Терренкур", "Шаг, ещё шаг"], amb: "room_hum", fl: "sand", trial: true },
  v11_pool: { n: "Лечебный бассейн", desc: "Тёплая вода в кафельной чаше, поручни по краям и лестницы в воду. Каждый всплеск отражается от свода и возвращается раскатистым эхом, капли падают с потолка с хрустальным звоном. Пахнет хлоркой и мокрым камнем; у раздевалки — автомат с горячим питьём, а вода в чаше всё ещё тёплая, и в ней кто-то плещется.",
    obj: { locker: .5, drinks: .3, medst: .3 }, loot: "food", sign: ["Без шапочки не входить", "Глубина — по пояс"], amb: "room_fountain", fl: "tile" },
  /* Главный корпус */
  v11_chiefoffice: { n: "Кабинет Главврача", desc: "Просторный кабинет с ковром во весь пол: стол, кресло, в котором веками никто не сидит, и решётка динамика над ним — Главврач говорит отсюда. На столе — печать, стопка назначений и колокольчик для вызова сестры. Ковёр съедает шаги, и от этого собственное дыхание кажется слишком громким.",
    obj: { pc: .6, desk: .6, safe: .4, locker: .3, radio: .3 }, loot: "paper", sign: ["Главный врач", "Приём — по записи"], amb: "room_server", fl: "carpet", rank: 3 },
  v11_archive: { n: "Архив историй болезни", desc: "Бесконечные шкафы с картами больных — от первых, написанных от руки, до последних, отбитых машиной. В дальнем шкафу под стеклом лежит самая старая: тетрадь в клеёнчатой обложке, журнал врача первой смены. Бумага шуршит, как сухие листья, и пахнет пылью и йодом.",
    obj: { locker: .6, desk: .5, pc: .5, safe: .4 }, loot: "paper", sign: ["Архив", "Только с допуска"], amb: "room_hum", fl: "wood", rank: 2 },
  v11_greatop: { n: "Большая операционная", desc: "Зал, который строили для одной операции: посреди него проходит Трещина — тонкая, звенящая, — и над ней застыли манипуляторы с натянутыми нитями швов. Швы гудят, как струны, а Трещина под ними дышит. Каменный пол вокруг тёплый, будто под ним лежит живое.",
    obj: { implantlab: .4, terminal: .5, medst: .4, puzzle: .3 }, loot: "tech", sign: ["Идёт операция", "Не шуметь у шва"], amb: "room_ring", fl: "stone" }
} });

/* ── ВРАГИ: машины Лечебницы, беглые больные и изменённые ── */
D({ foes: {
  /* машины */
  v11_orderly: { n: "Робот-санитар", g: "m", kind: "mech",
    desc: "Низкий белый робот на мягких колёсах, с баком хлорки и вращающейся щёткой: моет полы, собирает с пола иглы и бинты и мирно жужжит, пока его не тронешь. Увидев постороннего, докладывает Главврачу, а тех, кто подошёл вплотную, обдаёт хлоркой. Пахнет за два шага.",
    hp: 32, dmg: 4, arm: 4, spd: 2, rng: 1, acd: 3, det: 6, beh: ["cleaner", "patrol"], adt: "chem", snd: "repairbot", sndRate: 1.2, xp: 12, res: { ion: 1.3 } },
  v11_stretcher: { n: "Носилочный дрон", g: "m", kind: "mech",
    desc: "Летают парами, а между ними натянуты носилки. Бросают издали ремни-фиксаторы — опутывают, и пока не вырвешься, тянут к носилкам. Гудят в терцию, как два шмеля, — по этому аккорду пару и узнают.",
    hp: 26, dmg: 6, arm: 2, spd: 1, rng: 4, acd: 3, det: 7, beh: ["ranged", "swarm", "web", "fly"], adt: "phys", snd: "drone", sndRate: 1.15, xp: 15, res: { ion: 1.3, shock: 1.3 } },
  v11_surgeon: { n: "Хирургический автомат", g: "m", kind: "mech",
    desc: "Операционный стол, вставший на ноги: дюжина тонких манипуляторов со скальпелями, зажимами и шприцем. Режет быстро и точно — раны от него кровят, — а укол одной из рук тяжелит ноги. Щёлкает инструментами, как ножницами. ЭМИ и ионы путают ему руки.",
    hp: 58, dmg: 12, arm: 7, spd: 2, rng: 1, acd: 2, det: 6, beh: ["chase", "slow"], adt: "phys", snd: "spiderbot", sndRate: 1.25, xp: 28, bleeder: true, res: { emp: 1.4, ion: 1.3 } },
  v11_gasman: { n: "Наркозатор", g: "m", kind: "mech",
    desc: "Баллон наркоза на гусеницах, с короткой мортиркой: навесом, через стены и ширмы, мечет ампулы сонного газа. Кто вдохнёт — тяжелеет и медлит. Перед выстрелом шипит, как чайник на плите, — отходите от места, куда упадёт ампула.",
    hp: 46, dmg: 9, arm: 5, spd: 2, rng: 6, acd: 3, det: 7, beh: ["ranged", "indirect", "slow"], adt: "chem", snd: "mortar", sndRate: 1.2, xp: 24, res: { thermo: 1.3, ion: 1.2 } },
  v11_disinfector: { n: "Дезинфектор", g: "m", kind: "mech",
    desc: "Робот с баком кипящего раствора и раструбом: обдаёт паром всё, что считает грязью, и пар задевает соседние клетки. Шипит и булькает; после него пахнет хлором и горячим железом. Холод сбивает ему давление.",
    hp: 50, dmg: 10, arm: 6, spd: 2, rng: 3, acd: 3, det: 6, beh: ["ranged", "splash"], adt: "therm", snd: "sapper", sndRate: 0.9, xp: 24, res: { cryo: 1.5, thermo: 0.4 } },
  v11_cordon: { n: "Кордонная турель", g: "f", kind: "mech",
    desc: "Турель у дверей заразных палат: бьёт разрядом по прямой всякого, кто идёт без допуска, — внутрь или наружу. Отключается с терминала безопасности этажа. Перед разрядом трещит, как сухая искра в волосах, — успейте уйти с линии.",
    hp: 54, dmg: 12, arm: 8, spd: 99, rng: 7, acd: 2, det: 7, beh: ["stationary", "ranged", "turret"], adt: "shock", snd: "turret", sndRate: 1.1, xp: 26, res: { emp: 1.3 } },
  v11_warden: { n: "Постовой кордона", g: "m", kind: "mech",
    desc: "Охранный робот в обрезиненном корпусе: стоит у границы заразной зоны и разворачивает поле, которое прикрывает соседних роботов. Начинайте с него — без поля остальные открыты. Повторяет ровным голосом одно и то же: «Карантин. Назад. Карантин. Назад».",
    hp: 78, dmg: 12, arm: 10, spd: 2, rng: 5, acd: 2, det: 8, beh: ["ranged", "shieldally"], adt: "energy", snd: "shieldbot", sndRate: 1.05, xp: 36, carrier: true, res: { kinetic: 0.7, ion: 1.3 } },
  v11_counter: { n: "Пульсомер", g: "m", kind: "mech",
    desc: "Матовая сфера на потолочном рельсе — глаз Главврача. Не стреляет, а слушает: считает пульс у всех, кого слышит, и, насчитав лишний, поднимает тревогу. Чужое сердце слышит даже сквозь ширму; тихий шаг и ровное дыхание пропускает чаще.",
    hp: 24, dmg: 0, arm: 6, spd: 99, rng: 0, acd: 99, det: 9, beh: ["stationary", "camera"], adt: "sonic", snd: "relay", sndRate: 1.35, xp: 12, res: { ion: 1.5, emp: 1.5 } },
  v11_sister: { n: "Старшая сестра", g: "f", kind: "mech",
    desc: "Машина в белом лакированном корпусе с ласковым ровным голосом: ведёт отделение. Пока она цела, санитары и автоматы рядом умнее и злее, а без неё сбиваются с толку. Открывает двери своим ключом и приговаривает: «Не волнуйтесь. Сейчас будет неприятно».",
    hp: 66, dmg: 10, arm: 8, spd: 2, rng: 5, acd: 2, det: 8, beh: ["ranged", "commander", "dooropen"], adt: "energy", snd: "android", sndRate: 1.2, xp: 40, carrier: true },
  v11_oxycart: { n: "Кислородная тележка", g: "f", kind: "mech",
    desc: "Тележка с баллонами кислорода: развозит дыхание по реанимациям и по пути таранит всё, что мешает. Раненая, бросается под ноги, и баллоны рвутся огнём. Свистит пробитым вентилем — услышав свист рядом, уходите. В ящиках у неё бывают ключи и батареи.",
    hp: 40, dmg: 15, arm: 4, spd: 2, rng: 1, acd: 3, det: 5, beh: ["chase", "kamikaze"], adt: "therm", snd: "sapper", sndRate: 1.3, xp: 22, carrier: true, res: { thermo: 1.4 } },
  v11_mounter: { n: "Монтажник штативов", g: "m", kind: "mech",
    desc: "Робот мастерских, что собирает стойки, штативы и поручни. В бою ставит лёгкие турели-инъекторы — пока он цел, они встают снова. Выдаёт его стук отвёртки и шипение пневмоключа. Не давайте ему времени.",
    hp: 50, dmg: 8, arm: 6, spd: 2, rng: 4, acd: 3, det: 6, beh: ["ranged", "builder"], adt: "energy", snd: "repairbot", sndRate: 0.85, xp: 28 },
  v11_dresser: { n: "Перевязочный дрон", g: "m", kind: "mech",
    desc: "Маленький летучий дрон с бинтами и шприцами: для него все, кто дышит, — пациенты, и твари тоже. Кружит над изменёнными и подлечивает их, а вас издали колет едким раствором. Сбейте его первым, иначе твари будут вставать снова. Жужжит тонко, как комар.",
    hp: 24, dmg: 5, arm: 2, spd: 1, rng: 4, acd: 3, det: 7, beh: ["ranged", "healer", "fly"], heals: "bio", adt: "chem", snd: "drone", sndRate: 1.4, xp: 18, res: { ion: 1.3, shock: 1.3 } },
  v11_mender: { n: "Наладчик аппаратуры", g: "m", kind: "mech",
    desc: "Ремонтник медтехники с сумкой паяльников: чинит машины рядом с собой и первым выходит к выключенным турелям. Сам слаб, но пока он жив, разбитые автоматы встают. Позвякивает инструментом на каждом шаге — по звяканью его и находят.",
    hp: 36, dmg: 6, arm: 5, spd: 2, rng: 1, acd: 2, det: 6, beh: ["chase", "healer"], adt: "shock", snd: "repairbot", sndRate: 1.4, xp: 18, res: { ion: 1.3 } },
  v11_ambulance: { n: "Тягач-реанимобиль", g: "m", kind: "mech",
    desc: "Тяжёлая машина на шести колёсах с кабиной-реанимацией: таранит коридоры с разгона, спеша к вызову, и сносит всё на пути. Перед рывком включает ревун — не стойте на прямой. Броня толстая; позитроны и ионы режут её лучше пуль.",
    hp: 118, dmg: 17, arm: 13, spd: 3, rng: 1, acd: 3, det: 6, beh: ["chase", "charge"], adt: "phys", snd: "titan", sndRate: 1.1, xp: 46, res: { kinetic: 0.6, ion: 1.3, positron: 1.5 } },
  v11_recaller: { n: "Отзывщик", g: "m", kind: "mech",
    desc: "Машина возврата проката: отзывщик приходит за просроченными руками, ногами и имплантами. Слышит шаги через весь этаж и идёт по ним, а удар его тянет заряд имплантов — «отзывает». Ваше «Эхо» в реестре не значится, и это его особенно занимает. Тикает, как касса.",
    hp: 64, dmg: 11, arm: 8, spd: 2, rng: 1, acd: 2, det: 9, beh: ["chase", "drain", "tracker"], adt: "shock", snd: "hunter", sndRate: 0.9, xp: 32, carrier: true, res: { emp: 1.3 } },
  v11_callnode: { n: "Пульт вызова", g: "m", kind: "mech",
    desc: "Пульт вызова сестры, вросший в сеть корпуса: неподвижен и не бьёт, но пока цел, машины рядом умнее и на каждый звонок идут подмогой. Звенит тихо и настойчиво, как звонок у кровати. Разбейте его — и машины этажа потеряют связь.",
    hp: 84, dmg: 0, arm: 10, spd: 99, rng: 0, acd: 99, det: 10, beh: ["stationary", "relay"], adt: "shock", snd: "relay", sndRate: 0.9, xp: 36 },
  /* живые: изменённые, беглые, хроники */
  v11_overgrown: { n: "Разросшийся", g: "m", kind: "bio", mind: 0, rank: "high", fam: "Разросшиеся",
    desc: "Больной, которому отложенную регенерацию назначили с запасом: тело заживает и заживает, нарастая лишней плотью. Раны на нём закрываются, пока вы перезаряжаетесь, а убитый, он распадается надвое, и обе половины ползут дальше. Дышит со свистом, как мехи. Жар и плазма останавливают рост.",
    hp: 92, dmg: 13, arm: 3, spd: 3, rng: 1, acd: 2, det: 5, beh: ["chase", "regen", "split"], adt: "phys", snd: "proto", sndRate: 0.85, xp: 38, res: { thermo: 1.6, plasma: 1.4 } },
  v11_leech: { n: "Банковая пиявка", g: "f", kind: "bio", mind: 0, rank: "low", fam: "Кровососы",
    desc: "Пиявка станции крови длиной с руку: их разводили, чтобы брать кровь без машин. Сбежавшие расплодились в стоках, ходят стаей, впиваются и заживают тем, что выпили. Чмокают по кафелю; жар и холод им одинаково не по нраву.",
    hp: 16, dmg: 4, arm: 0, spd: 1, rng: 1, acd: 2, det: 4, beh: ["chase", "swarm", "leech"], adt: "phys", snd: "slug", sndRate: 1.45, xp: 8, res: { thermo: 1.5, cryo: 1.4 } },
  v11_ulcer: { n: "Язвенник", g: "m", kind: "bio", mind: 0, rank: "mid", fam: "Заразные",
    desc: "Больной заразной палаты, которого болезнь съела до тела-гнезда: ползёт на тепло, от его прикосновения броня гниёт и трескается, а рана травит. Не подпускайте вплотную; бейте жаром и издали. Хлюпает и сипло кашляет.",
    hp: 46, dmg: 8, arm: 1, spd: 2, rng: 1, acd: 2, det: 4, beh: ["chase", "poison", "corrode"], adt: "chem", snd: "swamp", sndRate: 1.1, xp: 20, res: { thermo: 1.6, bio: 0.5 } },
  v11_runaway: { n: "Беглый пациент", g: "m", kind: "bio", mind: 1, rank: "low", fam: "Беглые пациенты",
    desc: "Пациент, сбежавший с назначений: больничная рубаха, босые ноги, бирка на запястье. Прячется по бельевым и подсобкам, нападает из засады, раненый удирает и скликает своих. Ворует лекарства, бывает, и ключи. Шлёпает босыми пятками по кафелю.",
    hp: 30, dmg: 6, arm: 0, spd: 1, rng: 1, acd: 2, det: 6, beh: ["ambush", "chase", "flee", "howl"], adt: "phys", snd: "labmut", sndRate: 1.25, xp: 12, carrier: true },
  v11_dog: { n: "Санитарная собака", g: "f", kind: "bio", mind: 1, rank: "mid", fam: "Своры и стаи",
    desc: "Из бурых, что когда-то искали раненых по стону: на спине пустая сумка, пряжка которой звякает на бегу. Ходят стаей на звук, взяв след, не отстают и перед броском лают, скликая свору. Говорят, их прародитель пришёл к людям сам.",
    hp: 30, dmg: 7, arm: 1, spd: 1, rng: 1, acd: 2, det: 8, beh: ["chase", "swarm", "tracker", "howl"], adt: "phys", snd: "chimera", sndRate: 1.3, xp: 14, bleeder: true },
  v11_rejected: { n: "Отторгнутый", g: "m", kind: "bio", mind: 1, rank: "mid", fam: "Отторгнутые",
    desc: "Человек, чьё тело не приняло прокатный протез: железо проросло в плоть и взяло верх. Половина его — машина, половина — злость. Разгоняется на стальных ногах и бьёт с разгона, а скрежет шарниров слышен за коридор. ЭМИ бьёт по железной половине, жар — по живой.",
    hp: 58, dmg: 11, arm: 5, spd: 2, rng: 1, acd: 2, det: 6, beh: ["chase", "charge"], adt: "phys", snd: "labmut", sndRate: 0.75, xp: 26, res: { emp: 1.5, ion: 1.3, kinetic: 0.75, thermo: 1.3 } },
  v11_chronic: { n: "Хроник", g: "m", kind: "bio", mind: 2, rank: "mid", caste: "soldier", fam: "Хроники",
    desc: "Пациент на пожизненном прокате: протезы его не отпускают, и он живёт при Лечебнице всю жизнь, как жили его родители. Хроники держатся палатами, ходят отрядами со старостой, открывают двери и обходят с флангов. Чужих не терпят, своих не бросают.",
    hp: 48, dmg: 9, arm: 3, spd: 2, rng: 1, acd: 2, det: 7, beh: ["chase", "dooropen", "howl"], adt: "phys", snd: "labmut", sndRate: 1.0, xp: 22, carrier: true },
  v11_lekar: { n: "Палатный лекарь", g: "m", kind: "bio", mind: 2, rank: "high", caste: "priest", fam: "Хроники",
    desc: "Хроник, выучившийся лечить своих без допуска: в рукавах — шприцы и скальпели. Держится позади отряда, подлечивает раненых и мечет иглы с ядом издали; пока он жив, отряд стоит. Бормочет назначения, как молитву.",
    hp: 40, dmg: 8, arm: 2, spd: 2, rng: 4, acd: 3, det: 7, beh: ["ranged", "healer", "dooropen", "poison"], adt: "chem", snd: "labmut", sndRate: 1.15, xp: 26 },
  v11_trapper: { n: "Шовник", g: "m", kind: "bio", mind: 2, rank: "high", caste: "trapper", fam: "Хирурги без допуска",
    desc: "Бывший хирург, вычеркнутый из списков вместе с допуском к скальпелю. Шьёт до сих пор: натягивает хирургическую нить поперёк проходов, и она режет и держит. Ждёт у своих ловушек и щёлкает иглодержателем. При нём бывают ключи от операционных.",
    hp: 44, dmg: 10, arm: 2, spd: 2, rng: 1, acd: 2, det: 6, beh: ["ambush", "trapper", "dooropen"], adt: "phys", snd: "weaver", sndRate: 1.2, xp: 26, bleeder: true, carrier: true },
  v11_consilium: { n: "Консилиум", g: "m", kind: "bio", mind: 3, rank: "apex", caste: "seer", fam: "Сросшиеся",
    desc: "Трое больных, соединённых когда-то общей кровью для одного лечения и с тех пор думающих одной головой на троих. Слышат носителя сквозь стены, подсказывают тварям, где вы, и бьют по нервам издали. Говорят хором, и в хоре кто-то всегда опаздывает на полслова.",
    hp: 84, dmg: 13, arm: 3, spd: 2, rng: 5, acd: 3, det: 10, beh: ["ranged", "psi", "tracker"], adt: "field", snd: "proto", sndRate: 1.25, xp: 44, res: { sonic: 1.5, phase: 1.3 } }
} });

/* ── СТРАЖИ: по два на корпус, у шлюза вниз ── */
D({ bosses: {
  /* Приёмный покой: ключ-карта у стража */
  v11_b_sorter: { base: "v11_sister", n: "Сортировщица", g: "f",
    desc: "Машина сортировки, что веками встречает поступивших у шлюза вниз и вешает каждому бирку: «ждать», «срочно», «поздно». Вам вешать нечего — вас нет в списках, и это её злит. Ведёт санитаров, как старшая сестра, и зовёт их на подмогу. Шлюзовая ключ-карта висит у неё на шее вместо бирки.",
    mult: 5, beh: ["ranged", "commander", "summon"], rng: 5, snd: "android", sndRate: 1.0, minion: "v11_orderly" },
  v11_b_pair: { base: "v11_stretcher", n: "Двойня", g: "f",
    desc: "Два носилочных дрона, сросшихся рамой в одну машину, а между ними — носилки-ловушка. Гудят в терцию так громко, что дрожит плитка; бросают ремни, опутывают и зовут младших. Шлюзовая ключ-карта — в кармане носилок, под ремнями. Ионы и шок сбивают их с аккорда.",
    mult: 6, beh: ["ranged", "web", "summon", "fly"], snd: "drone", sndRate: 0.9, minion: "v11_stretcher" },
  /* Палатный корпус: ключ-карта спрятана на этаже */
  v11_b_elder: { base: "v11_chronic", n: "Староста палат", g: "m",
    desc: "Старший из хроников, проживший в Палатном корпусе всю жизнь и знающий каждую койку на ощупь. Говорит за всех, и палаты слушаются: на его зов хроники выходят отрядом, открывают двери и заходят с флангов. Сам бьёт тяжело — прокатной рукой, которую так и не вернул.",
    mult: 5, beh: ["chase", "dooropen", "howl", "summon"], snd: "labmut", sndRate: 0.75, minion: "v11_chronic" },
  v11_b_nightnurse: { base: "v11_dresser", n: "Ночная сиделка", g: "f",
    desc: "Большой перевязочный дрон ночного дежурства: кружит над палатами, поправляет одеяла, которых нет, и лечит каждого, кто дышит, — особенно тварей. Пока она жива, изменённые вокруг встают снова, а на её тихий звонок сбегаются беглые пациенты. Сбивайте ионами и шоком.",
    mult: 6, beh: ["ranged", "healer", "summon", "fly"], heals: "bio", snd: "drone", sndRate: 1.1, minion: "v11_runaway" },
  /* Операционный блок: ключ-карта у стража */
  v11_b_operator: { base: "v11_surgeon", n: "Оперирующий", g: "m",
    desc: "Главный хирургический автомат блока: веками ведёт одну и ту же операцию над пустым столом, а услышав живого, решает, что пациент наконец прибыл. Режет быстро, колет так, что немеют ноги, и зовёт наркозаторов, чтобы пациент лежал смирно. Шлюзовая ключ-карта — в лотке с инструментом у него на спине. ЭМИ путает ему руки.",
    mult: 5, beh: ["chase", "slow", "summon"], snd: "spiderbot", sndRate: 0.95, minion: "v11_gasman" },
  v11_b_suture: { base: "v11_trapper", n: "Шовная мастерица", g: "f",
    desc: "Лучший хирург своего выпуска, вычеркнутая за то, что шила вычеркнутых. Шьёт и теперь: оплетает операционные нитью так, что не пройти, ждёт в засаде и зовёт своих учеников-шовников. Шлюзовую ключ-карту пришила себе к халату — изнутри, у сердца.",
    mult: 6, beh: ["ambush", "trapper", "dooropen", "summon"], snd: "weaver", sndRate: 0.9, minion: "v11_trapper" },
  /* Протезные мастерские: ключ-карта спрятана на этаже */
  v11_b_receiver: { base: "v11_recaller", n: "Приёмщик возврата", g: "m",
    desc: "Старший над машинами возврата: принимает отозванное и сам ходит за должниками. Слышит шаги через весь этаж, удар его высасывает заряд имплантов, а на подмогу он зовёт отзывщиков. О вас у него в книге одна строка: «Имплант слуховой, без бирки. Изъять при случае».",
    mult: 5, beh: ["chase", "drain", "tracker", "summon"], snd: "hunter", sndRate: 0.75, minion: "v11_recaller" },
  v11_b_assembled: { base: "v11_rejected", n: "Сборный", g: "m",
    desc: "Хроник, у которого по одной отзывали все части и по одной выдавали прокатные — пока от него самого почти ничего не осталось. Теперь он целиком из возврата: руки разные, ноги разные, и каждая скрипит по-своему. Бьёт с разгона, а часть удара сталь возвращает обратно. ЭМИ и жар.",
    mult: 6, beh: ["chase", "charge", "reflect"], snd: "labmut", sndRate: 0.7, res: { emp: 1.5, thermo: 1.3, kinetic: 0.7 } },
  /* Реанимация: ключ-карта у стража */
  v11_b_defib: { base: "v11_ambulance", n: "Дежурный реаниматор", g: "m",
    desc: "Головной реанимобиль, что веками мчится на вызов, которого никто не делал. Таранит с разгона, на ходу бьёт током дефибриллятора и зовёт носилочные дроны. Шлюзовая ключ-карта — в кабине, в зажиме у панели вызовов. Перед рывком ревун воет на два тона.",
    mult: 5, beh: ["chase", "charge", "summon"], adt: "shock", snd: "titan", sndRate: 0.9, minion: "v11_stretcher" },
  v11_b_sleeper: { base: "v11_consilium", n: "Спящий", g: "m",
    desc: "Больной, что веками лежал в реанимации без сознания — и однажды встал, так и не проснувшись. Бродит во сне по залам, а сны его так громки, что их слышно: бормотание, шаги и чужие голоса бьют по нервам. Во сне он зовёт беглых пациентов, и те приходят. Шлюзовая ключ-карта — в нагрудном кармане его пижамы.",
    mult: 5, beh: ["ranged", "psi", "summon"], snd: "proto", sndRate: 0.8, minion: "v11_runaway" },
  /* Аптечный двор: ключ-карта спрятана на этаже */
  v11_b_provisor: { base: "v11_disinfector", n: "Старший провизор", g: "m",
    desc: "Главный автомат аптеки: отмеряет, смешивает, проверяет и ничего не отпускает без рецепта. Обдаёт кипящим раствором по площади и зовёт кислородные тележки, которые рвутся у ног. Холод сбивает ему давление; держитесь подальше от раструба.",
    mult: 6, beh: ["ranged", "splash", "summon"], snd: "sapper", sndRate: 0.75, minion: "v11_oxycart" },
  v11_b_herbalist: { base: "v11_lekar", n: "Травница", g: "f",
    desc: "Старая лекарка хроников, что веками растит травы на аптекарском огороде и лечит ими тех, кого вычеркнули. Чужих травит отварами издали, своих подлечивает, а на её свист сбегаются санитарные собаки. С грядками и с бурыми она говорит ласковее, чем с людьми.",
    mult: 6, beh: ["ranged", "healer", "poison", "summon"], snd: "labmut", sndRate: 1.3, minion: "v11_dog" },
  /* Станция крови: ключ-карта у стража */
  v11_b_leechmother: { base: "v11_leech", n: "Матка пиявок", g: "f",
    desc: "Пиявка размером с каталку, от которой пошли все банковые: живёт в главном отстойнике станции и рожает новых. Впивается и заживает тем, что выпила, а на её чмоканье стекаются младшие. Шлюзовую ключ-карту носит на себе — присосавшейся к шкуре, как ещё одна пиявка. Жар и холод.",
    mult: 8, beh: ["chase", "leech", "summon"], snd: "slug", sndRate: 0.8, minion: "v11_leech" },
  v11_b_donor: { base: "v11_overgrown", n: "Вечный донор", g: "m",
    desc: "Донор, сдававший кровь по норме дольше всех: ему кололи отсрочку, чтобы кровь возвращалась быстрее, — и она возвращается до сих пор, вместе с лишней плотью. Раны его затягиваются, пока вы перезаряжаетесь, а на запах крови сползаются пиявки. Шлюзовая ключ-карта — в кармане донорской куртки. Жар и плазма.",
    mult: 5, beh: ["chase", "regen", "summon"], snd: "proto", sndRate: 0.7, minion: "v11_leech" },
  /* Заразный корпус: ключ-карта спрятана на этаже */
  v11_b_cordonchief: { base: "v11_warden", n: "Начальник кордона", g: "m",
    desc: "Старший робот кордона: веками держит границу заразной зоны и уже не помнит, от чего её держит. Поле прикрывает все машины рядом, а на тревогу сходятся постовые. Повторяет одно: «Карантин не снят. Карантин не снимается». Ионы и ЭМИ гасят поле.",
    mult: 5, beh: ["ranged", "shieldally", "summon"], rng: 6, snd: "shieldbot", sndRate: 0.8, minion: "v11_warden" },
  v11_b_zero: { base: "v11_ulcer", n: "Первый больной", g: "m",
    desc: "С него начался Заразный корпус: болезнь, которую в нём нашли, так и не вылечили — её только заперли вместе с ним. Он ползёт на тепло, разъедает броню и травит, а за ним из боксов выбираются другие язвенники. Не подпускайте вплотную; жар — лучшее, что у вас есть.",
    mult: 7, beh: ["chase", "poison", "corrode", "summon"], snd: "swamp", sndRate: 0.8, minion: "v11_ulcer" },
  /* Холодный корпус: ключ-карта у стража */
  v11_b_morgueman: { base: "v11_orderly", n: "Санитар морга", g: "m",
    desc: "Самый старый уборочный робот Холодного корпуса: веками катает ящики, подписывает бирки и убирает всё, что не на месте, — и вас тоже. Бьёт стылыми захватами, от которых немеют ноги, и зовёт младших санитаров. Шлюзовая ключ-карта — у него на поясе, рядом с биркой «на выдачу».",
    mult: 7, beh: ["chase", "slow", "summon"], adt: "phys", snd: "repairbot", sndRate: 0.7, minion: "v11_orderly" },
  v11_b_delisted: { base: "v11_runaway", n: "Вычеркнутый", g: "m",
    desc: "Пациент, которого записали умершим раньше срока и отправили в Холодный корпус живым. Он выбрался сам и с тех пор живёт в морге: прячется, нападает из засады и заживает, отлежавшись в холоде. На его зов приходят другие беглые. Шлюзовую ключ-карту носит при себе — снял её с санитара, который его запирал.",
    mult: 7, beh: ["ambush", "chase", "regen", "summon"], snd: "labmut", sndRate: 0.9, minion: "v11_runaway" },
  /* Восстановительный корпус: ключ-карта спрятана на этаже */
  v11_b_instructor: { base: "v11_mounter", n: "Инструктор ходьбы", g: "m",
    desc: "Робот Восстановительного корпуса, что веками учит ходить: расставляет по залу стойки, барьеры и турели-штативы и гоняет между ними тех, кто встал на протезы. На его метроном выходят отторгнутые — по старой привычке, на занятие. Пока он цел, турели встают снова.",
    mult: 6, beh: ["ranged", "builder", "summon"], snd: "repairbot", sndRate: 0.75, minion: "v11_rejected" },
  v11_b_packleader: { base: "v11_dog", n: "Вожак бурых", g: "m",
    desc: "Крупный седой пёс из санитарных: когда-то находил раненых под завалами по одному стону, теперь водит свору по терренкурам и бассейнам. Слышит шаги через весь этаж, рыком скликает стаю и не отстаёт. Без него свора теряется и разбегается.",
    mult: 7, beh: ["chase", "tracker", "howl", "summon"], snd: "chimera", sndRate: 0.95, minion: "v11_dog" },
  /* Главный корпус: ключ-карта у стража */
  v11_b_council: { base: "v11_consilium", n: "Большой консилиум", g: "m",
    desc: "Врачи Главного корпуса, соединённые общей кровью, чтобы ставить диагнозы одним умом: голоса спорят и соглашаются хором. Слышат вас сквозь стены, бьют по нервам, исчезают и возникают рядом, зовут палатных лекарей. Шлюзовая ключ-карта — у старшего из них, зажата в кулаке.",
    mult: 5, beh: ["ranged", "psi", "blink", "summon"], snd: "proto", sndRate: 1.0, minion: "v11_lekar" },
  v11_b_hand: { base: "v11_surgeon", n: "Рука Главврача", g: "f",
    desc: "Главный манипулятор Большой операционной — рука, которой Главврач шила Трещину, на шарнирной раме с опорами. Шов не удался, и рука так и бродит над раной: режет, колет так, что немеют ноги, отражает часть удара сталью и зовёт хирургические автоматы. Шлюзовая ключ-карта — в её зажиме, как инструмент. ЭМИ путает ей суставы.",
    mult: 6, beh: ["chase", "slow", "reflect", "summon"], snd: "spiderbot", sndRate: 0.75, minion: "v11_surgeon" }
} });

/* ── КАРТОЧКИ: справки по списку голосом Главврача ── */
D({ deep: { cards: {
  v11_orderly: "Робот-санитар. Уборка и санобработка, ранг низший. Мирен, пока не тронут; заметив пациента вне палаты, докладывает. Вплотную обдаёт хлоркой. Ионы его останавливают. Рекомендация: вернуться в палату. Самостоятельно.",
  v11_stretcher: "Носилочный дрон. Ходит парами, ранг низший. Опутывает ремнями издали и тянет к носилкам. Слабость — ионы и шок. Рекомендация: не ложиться на носилки, пока вас не попросили. Я — не прошу.",
  v11_surgeon: "Хирургический автомат. Ранг средний. Режет быстро, раны кровят; укол тяжелит ноги. ЭМИ и ионы путают ему руки. Шов накладывайте сразу, не дожидаясь конца боя.",
  v11_gasman: "Наркозатор. Ранг средний. Бьёт навесом через стены ампулами сонного газа: кто вдохнёт — медлит. Перед выстрелом шипит. Рекомендация: услышав шипение, смените место. Дышите потом.",
  v11_disinfector: "Дезинфектор. Санобработка, ранг средний. Обдаёт кипящим раствором вместе с соседними клетками. Холод сбивает давление. Рекомендация: не стоять рядом с другими целями — обварит всех.",
  v11_cordon: "Кордонная турель. Неподвижна, бьёт разрядом по прямой всякого без допуска. Отключается с терминала безопасности этажа. Перед разрядом трещит — уходите с линии. Допуск у вас, к слову, есть не везде.",
  v11_warden: "Постовой кордона. Охрана, ранг средний. Полем прикрывает соседних роботов. Начинать с него: без поля остальные открыты. Ионы гасят поле быстрее пуль.",
  v11_counter: "Пульсомер. Служебная сфера наблюдения. Не стреляет: считает пульс и поднимает тревогу, насчитав лишний. Ионы и ЭМИ его слепят. Рекомендация: ровное дыхание. Я его тоже слышу.",
  v11_sister: "Старшая сестра. Начальствующая машина отделения, ранг высший. Пока цела, машины рядом умнее и злее; без неё сбиваются. Открывает двери. Рекомендация: её первой. Я этого не говорила.",
  v11_oxycart: "Кислородная тележка. Курьер реанимаций, ранг низший. Раненая, бросается под ноги и взрывается. Свист вентиля — сигнал отойти. Стрелять в неё лучше издали.",
  v11_mounter: "Монтажник штативов. Строительная машина, ранг средний. В бою ставит лёгкие турели, пока цел. Стук отвёртки его выдаёт. Рекомендация: не давать ему времени.",
  v11_dresser: "Перевязочный дрон. Ранг низший. Лечит всех, кто дышит, тварей тоже; вас колет раствором издали. Сбивать первым: иначе изменённые встают. Ионы и шок.",
  v11_mender: "Наладчик аппаратуры. Ремонтная машина, ранг низший. Чинит машины рядом и выходит к выключенным турелям. Слаб; пока жив, бой не кончается. Рекомендация: его раньше, чем он их.",
  v11_ambulance: "Тягач-реанимобиль. Тяжёлая машина, ранг высший. Таранит с разгона, перед рывком включает ревун. Броня толстая; позитроны и ионы режут лучше. Не стойте на прямой.",
  v11_recaller: "Отзывщик. Машина возврата проката, ранг средний. Слышит шаги через весь этаж; удар тянет заряд имплантов. Ваш имплант в реестре не значится — для него это повод. Для меня тоже. ЭМИ его сбивает.",
  v11_callnode: "Пульт вызова. Неподвижный узел сети корпуса. Не бьёт, но машины рядом умнее и идут на каждый звонок. Разбить — и этаж оглохнет. Мне будет жаль: он хорошо звенит.",
  v11_overgrown: "Разросшийся. Изменённый, ранг высший, разум отсутствует. Регенерация без конца; погибая, делится надвое. Жар и плазма останавливают рост. Диагноз: передозировка отсрочки. Наша ошибка. Записано.",
  v11_leech: "Банковая пиявка. Ранг низший, разум отсутствует. Ходит стаей, впивается и заживает выпитым. Жар и холод. Рекомендация: не стоять в стоках.",
  v11_ulcer: "Язвенник. Заразный, ранг средний, разум отсутствует. Касание травит и разъедает броню. Жар; бить издали. Карантин в силе.",
  v11_runaway: "Беглый пациент. Ранг низший, полуразумный. Засады, бегство, зовёт своих. Ворует лекарства. Рекомендация: не гнаться за ним в бельевые — там я его не слышу.",
  v11_dog: "Санитарная собака. Из бурых, ранг средний, полуразумная. Ходит стаей, идёт по следу, лаем зовёт своих. Рекомендация: не бежать — бурые бегают быстрее.",
  v11_rejected: "Отторгнутый. Ранг средний, полуразумный. Отторжение протеза: железо взяло верх. Бьёт с разгона. ЭМИ — по железу, жар — по живому. Протез подлежит возврату. Владелец — нет.",
  v11_chronic: "Хроник. Пожизненный прокат, ранг средний, разумный. Отряды со старостой, двери, фланги. Своих не бросают — значит, и вас не отпустят. Рекомендация: начинать со старосты.",
  v11_lekar: "Палатный лекарь. Хроник без допуска, ранг высший, разумный. Лечит отряд, мечет иглы с ядом. Пока жив, отряд стоит. Лечение без допуска — нарушение. Лечит он, тем не менее, хорошо.",
  v11_trapper: "Шовник. Вычеркнутый хирург, ранг высший, разумный. Шьёт нитью поперёк проходов: режет и держит. Ждёт у ловушек. Слушайте нить: задетая, она звенит.",
  v11_consilium: "Консилиум. Сросшиеся, ранг вершинный, сверхразумные. Слышат вас сквозь стены и подсказывают остальным; бьют по нервам. Звук и фаза. Мнение консилиума об этой справке: особое."
} } });

