    v11_plasma: { n: "Донорская плазма", icon: "🩸", from: "bio", desc: "Пакет густой плазмы со станции крови, с биркой и датой: её выпивают пиявки и копят разросшиеся. Основа переливаний и наркозного эфира. Держать в холоде, не встряхивать.", price: 34, at: 0.2 },
    v11_regen: { n: "Живой регенерат", icon: "🧬", from: "bio", desc: "Клетки разросшихся, которые не умеют перестать заживать: тёплый комок в банке, тихо пульсирующий в ладони. Из него варят капсулы отложенного заживления, а протезисты прокладывают им суставы экзоскелетов, чтобы те не стирались.", price: 44, at: 0.4 }
